      const callOrder: string[] = [];

      const hooks = recordingHooks(callOrder, [
        'beforeSession',
        'beforeUserInput',
        'afterUserInput',
        'beforeModelResponse',
        'afterModelResponse',
        'onError',
        'afterSession',
      ]);

